ALTER DATABASE SalesDB SET RECOVERY FULL;
GO
BACKUP DATABASE SalesDB
TO DISK = N'D:\Backups\SalesDB_Full.bak'
WITH FORMAT, INIT, SKIP, NOREWIND, NOUNLOAD, STATS = 10;

BACKUP LOG SalesDB
TO DISK = N'D:\Backups\SalesDB_Log.trn'
WITH FORMAT, INIT, SKIP, NOREWIND, NOUNLOAD, STATS = 10;

RESTORE DATABASE SalesDB
FROM DISK = N'D:\Backups\SalesDB_Full.bak'
WITH NORECOVERY, REPLACE;

RESTORE DATABASE SalesDB
FROM DISK = N'D:\Backups\SalesDB_Diff.bak'
WITH NORECOVERY;

RESTORE LOG SalesDB
FROM DISK = N'D:\Backups\SalesDB_Log.trn'
WITH RECOVERY, STOPAT = N'2025-06-15T14:30:00';
